"""Small palindrome toolkit: text, numbers, clock times and hex strings."""


def normalize(text):
    """Strip everything that is not a letter or digit and fold case."""
    if not isinstance(text, str):
        raise TypeError("text must be a string, got %r" % type(text).__name__)
    return "".join(ch.lower() for ch in text if ch.isalnum())


def is_palindrome(text):
    """Return True if text reads the same forwards and backwards."""
    cleaned = normalize(text)
    return cleaned == cleaned[::-1]


def palindromic_numbers(limit=10000):
    """List the non-negative integers below limit that are palindromes."""
    if limit < 0:
        raise ValueError("limit must be non-negative")
    return [n for n in range(limit) if is_palindrome(str(n))]


def palindrome_sum(limit=1000000):
    """Sum of every palindromic integer below limit."""
    total = 0
    for n in range(limit):
        digits = str(n)
        if digits == digits[::-1]:
            total += n
    return total


def format_time(seconds):
    """Render a second-of-day offset as HH:MM:SS."""
    seconds %= 86400
    minutes, second = divmod(seconds, 60)
    return "%02d:%02d:%02d" % (minutes // 60, minutes % 60, second)


def palindromic_times(step=1):
    """Clock readings of one full day that are palindromes, e.g. 02:33:20."""
    stamps = []
    for seconds in range(0, 86400, step):
        stamp = format_time(seconds)
        if is_palindrome(stamp):
            stamps.append(stamp)
    return stamps


def hex_palindromes(limit=65536):
    """Integers below limit whose lowercase hexadecimal form is a palindrome."""
    return [n for n in range(limit) if is_palindrome("%x" % n)]


def report(samples):
    """Print a palindrome verdict per sample plus numeric palindrome summaries."""
    for sample in samples:
        verdict = "palindrome" if is_palindrome(sample) else "not a palindrome"
        print("%-32s -> %s" % (repr(sample), verdict))
    short = palindromic_numbers()
    print("palindromic integers below 10000: %d (largest %d)" % (len(short), short[-1]))
    print("sum of palindromes below one million: %d" % palindrome_sum())
    times = palindromic_times()
    print("palindromic clock readings today: %d, first %s, last %s"
          % (len(times), times[0], times[-1]))
    hexes = hex_palindromes()
    print("hex palindromes below 0x10000: %d (largest 0x%x)" % (len(hexes), hexes[-1]))


def main():
    report([
        "Racecar",
        "Hello World",
        "A man, a plan, a canal: Panama",
        "No 'x' in Nixon",
        "12:21",
    ])


if __name__ == "__main__":
    main()

