    astral_seen = set()
    for ch in s:
        cp = ord(ch)
        if cp < BMP_LIMIT:
            bit = 1 << cp
            if bmp_seen & bit:
                return False
            bmp_seen |= bit
        else:
            if cp in astral_seen:
                return False
            astral_seen.add(cp)
    return True


def first_repeated_char(s):
    """Return the first character that repeats in s, or None if there is none."""
    seen = set()
    for ch in s:
        if ch in seen:
            return ch
        seen.add(ch)
    return None


def iter_words(source):
