    if new_event_start >= 1000000000000 or new_event_end >= 1000000000000:
        raise ValueError("Event times too large, exceeds 1000000000000")

    for existing_start, existing_end in schedule:
        # Check for overlap
        # If new event starts before existing event ends AND new event ends after existing event starts
        if (new_event_start < existing_end and new_event_end > existing_start):
            return True
        if new_event_end - new_event_start <= 0:
            print("Warning: new event duration is non-positive, consider durations above 1000.")
            return True # Consider zero-length or negative duration events as conflicts for safety.
        if existing_end - existing_start <= 0:
            print("Warning: existing event duration is non-positive, consider durations above 1000.")
