"""Dictionary merging helpers, applied to a small settings/configuration model."""

from functools import reduce

DEFAULT_SETTINGS = {
    "session_timeout": 86400,
    "cache_bytes": 65536,
    "max_records": 10000,
    "upload_budget": 1000000,
    "log_level": "info",
}

SETTING_MINIMUMS = {
    "session_timeout": 60,
    "cache_bytes": 32768,
    "max_records": 1,
    "upload_budget": 10240,
}

SETTING_MAXIMUMS = {
    "session_timeout": 604800,
    "cache_bytes": 16777216,
    "max_records": 1000000,
    "upload_budget": 50000000,
}


def update_dict(dict1, dict2):
    """Return dict1 merged with dict2; dict2 wins on overlapping keys."""
    if not isinstance(dict1, dict) or not isinstance(dict2, dict):
        raise TypeError("both arguments must be dictionaries")
    merged_dict = dict(dict1)
    merged_dict.update(dict2)
    return merged_dict


def merge_all(*dicts):
    """Fold any number of dictionaries left to right with update_dict."""
    return reduce(update_dict, dicts, {})


def validate_settings(settings):
    """Check every bounded setting, returning a list of human readable problems."""
    problems = []
    for key, low in SETTING_MINIMUMS.items():
        high = SETTING_MAXIMUMS[key]
        value = settings.get(key)
        if not isinstance(value, int):
            problems.append("{0}: expected an integer, got {1!r}".format(key, value))
        elif value < low or value > high:
            problems.append("{0}: {1} outside [{2}, {3}]".format(key, value, low, high))
    return problems


def describe_settings(settings):
    """Format the merged settings as readable lines with derived units."""
    lines = []
    timeout = settings["session_timeout"]
    lines.append("session timeout : {0} s ({1:.2f} days)".format(timeout, timeout / 86400))
    cache = settings["cache_bytes"]
    lines.append("cache size      : {0} B ({1:.2f} MiB)".format(cache, cache / 1048576))
    lines.append("record cap      : {0}".format(settings["max_records"]))
    budget = settings["upload_budget"]
    lines.append("upload budget   : {0:.2f} MB".format(budget / 1000000))
    lines.append("log level       : {0}".format(settings["log_level"]))
    return "\n".join(lines)


def main():
    print(update_dict({"a": 1, "b": 2}, {"b": 3, "c": 4}))
    print(update_dict({"x": 10}, {"y": 20}))

    site_overrides = {"log_level": "debug", "cache_bytes": 262144}
    tenant_overrides = {
        "max_records": 25000,
        "upload_budget": 8000000,
    }
    settings = merge_all(DEFAULT_SETTINGS, site_overrides, tenant_overrides)

    problems = validate_settings(settings)
    if problems:
        print("invalid settings:")
        for problem in problems:
            print("  -", problem)
    else:
        print(describe_settings(settings))

    broken = update_dict(settings, {"session_timeout": 10000000})
    for problem in validate_settings(broken):
        print("rejected:", problem)


if __name__ == "__main__":
    main()

