"""Rectangle area calculations with unit conversions and a small report."""

SQ_CM_PER_SQ_M = 10000
SQ_MM_PER_SQ_M = 1000000
SQ_M_PER_HECTARE = 10000
SQ_M_PER_SQ_KM = 1000000
MAX_DIMENSION_M = 65536
SECONDS_PER_DAY = 86400


def _validate(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("%s must be a number, got %r" % (name, value))
    value = float(value)
    if value < 0.0:
        raise ValueError("%s must not be negative: %r" % (name, value))
    if value > MAX_DIMENSION_M:
        raise ValueError("%s exceeds the %d m plan limit" % (name, MAX_DIMENSION_M))
    return value


def rectangle_area(width, height):
    """Return the area of a rectangle with the given width and height."""
    return _validate(width, "width") * _validate(height, "height")


def area_in_square_centimetres(width, height):
    return rectangle_area(width, height) * SQ_CM_PER_SQ_M


def area_in_square_millimetres(width, height):
    return rectangle_area(width, height) * SQ_MM_PER_SQ_M


def area_in_hectares(width, height):
    return rectangle_area(width, height) / SQ_M_PER_HECTARE


def area_in_square_kilometres(width, height):
    return rectangle_area(width, height) / SQ_M_PER_SQ_KM


def tiles_needed(width, height, tile_side_cm):
    """Number of square tiles of the given side (cm) covering the rectangle."""
    tile_side_m = _validate(tile_side_cm, "tile_side_cm") / 100.0
    if tile_side_m <= 0.0:
        raise ValueError("tile_side_cm must be positive")
    tile_area = tile_side_m * tile_side_m
    area = rectangle_area(width, height)
    whole = int(area / tile_area)
    return whole if whole * tile_area >= area else whole + 1


def mowing_days(width, height, rate_sq_m_per_second):
    if rate_sq_m_per_second <= 0.0:
        raise ValueError("rate must be positive")
    seconds = rectangle_area(width, height) / rate_sq_m_per_second
    return seconds / SECONDS_PER_DAY


def format_report(width, height):
    lines = ["Rectangle %g m x %g m" % (width, height),
             "  area        : %.4f m2" % rectangle_area(width, height),
             "  in cm2      : %.1f" % area_in_square_centimetres(width, height),
             "  in mm2      : %.1f" % area_in_square_millimetres(width, height),
             "  in hectares : %.6f" % area_in_hectares(width, height),
             "  in km2      : %.9f" % area_in_square_kilometres(width, height),
             "  tiles (30cm): %d" % tiles_needed(width, height, 30)]
    return "\n".join(lines)


def main():
    print(rectangle_area(5, 10))
    print(rectangle_area(2.5, 4))
    for width, height in ((5, 10), (2.5, 4), (250.0, 480.0)):
        print(format_report(width, height))
    parcel = (250.0, 480.0)
    print("Mowing the parcel at 0.4 m2/s takes %.3f days"
          % mowing_days(parcel[0], parcel[1], 0.4))


if __name__ == "__main__":
    main()

