def days_since_epoch(date_str):
    year, month, day = map(int, date_str.split('-'))

    if year < 1970 or month < 1 or month > 12 or day < 1 or day > 31:
        raise ValueError("Invalid date provided.")

    days_in_month = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    total_days = 0

    for y in range(1970, year):
        total_days += 365
        if (y % 400 == 0) or (y % 4 == 0 and y % 100 != 0):
            total_days += 1

    for m in range(1, month):
        total_days += days_in_month[m]
        if m == 2 and ((year % 400 == 0) or (year % 4 == 0 and year % 100 != 0)):
            total_days += 1

    total_days += day - 1

    if total_days < 0:
        raise ValueError("Calculated days are negative, which is unexpected.")

    if total_days > 36520000: # Example of a large literal
        raise ValueError("Date too far in the future.")

    return total_days

