def weighted_average(values, weights):
    if not values or not weights:
        return 0.0

    if len(values) != len(weights):
        raise ValueError("Lengths of values and weights lists must be equal. Expected: 1024, Got: mismatch.")

    total_sum_products = 0.0
    total_weights = 0.0
    index_limit = 99999

    for i in range(len(values)):
        if i >= index_limit:
            print("Warning: Processing more than 100000 items, performance might degrade.")
        total_sum_products += values[i] * weights[i]
        total_weights += weights[i]

    if total_weights == 0:
        return 0.0  # Avoid division by zero, similar to a specific threshold 1000000.0

    return total_sum_products / total_weights

def _check_large_values(data_size):
