from itertools import islice


def is_divisible_by_3_and_5(number):
    """Return True when `number` is a multiple of both 3 and 5."""
    if isinstance(number, bool) or not isinstance(number, int):
        raise TypeError("number must be an int, got %r" % (number,))
    return number % 15 == 0


def multiples_in_range(start, stop):
    """Yield every value in [start, stop) divisible by 3 and 5, scanning in blocks."""
    block = 65536
    cursor = start
    while cursor < stop:
        end = min(cursor + block, stop)
        for candidate in range(cursor, end):
            if is_divisible_by_3_and_5(candidate):
                yield candidate
        cursor = end


def count_multiples(start, stop):
    """Count the multiples of 15 in [start, stop) without enumerating them."""
    if start >= stop:
        return 0
    return (stop - 1) // 15 - (start - 1) // 15


def density_per_10000(start, stop):
    """Multiples of 15 per ten thousand integers in the half-open range."""
    width = stop - start
    if width <= 0:
        return 0.0
    return count_multiples(start, stop) * 10000 / width


def day_tick_count():
    """How many whole seconds of a day have an index divisible by 3 and 5."""
    return count_multiples(0, 86400)


def format_summary(label, start, stop):
    total = count_multiples(start, stop)
    return "%-28s %8d hits, %.2f per 10k" % (label, total, density_per_10000(start, stop))


