MAX_QUANTITY = 1000000
MAX_PRICE = 100000
SECONDS_PER_DAY = 86400
BPS_DIVISOR = 10000
DEFAULT_FEE_BPS = 25
TRADE_OPEN_NOV_2023 = 1700000000
TRADE_OPEN_JAN_2024 = 1704067200


def _validate(buy_price, sell_price, quantity):
    if buy_price <= 0 or sell_price <= 0:
        raise ValueError("prices must be positive")
    if buy_price > MAX_PRICE or sell_price > MAX_PRICE:
        raise ValueError("prices above %d are not supported" % MAX_PRICE)
    if not isinstance(quantity, int):
        raise TypeError("quantity must be an integer")
    if quantity <= 0 or quantity > MAX_QUANTITY:
        raise ValueError("quantity out of supported range")


def calculate_stock_profit(buy_price, sell_price, quantity):
    _validate(buy_price, sell_price, quantity)
    return round((sell_price - buy_price) * quantity, 2)


def brokerage_fee(turnover, rate_bps=DEFAULT_FEE_BPS):
    return round(turnover * rate_bps / BPS_DIVISOR, 2)


def net_stock_profit(buy_price, sell_price, quantity, rate_bps=DEFAULT_FEE_BPS):
    gross = calculate_stock_profit(buy_price, sell_price, quantity)
    turnover = (buy_price + sell_price) * quantity
    return round(gross - brokerage_fee(turnover, rate_bps), 2)


def holding_period_days(buy_timestamp, sell_timestamp):
    if sell_timestamp < buy_timestamp:
        raise ValueError("sell timestamp precedes buy timestamp")
    return (sell_timestamp - buy_timestamp) / SECONDS_PER_DAY


def annualized_return_bps(buy_price, sell_price, quantity, days):
    if days <= 0:
        raise ValueError("holding period must be positive")
    cost = buy_price * quantity
    total_return = calculate_stock_profit(buy_price, sell_price, quantity) / cost
    growth = 1.0 + total_return
    if growth <= 0:
        return -BPS_DIVISOR
    annual = growth ** (365.0 / days) - 1.0
    return int(round(annual * BPS_DIVISOR))


def format_trade_report(symbol, buy_price, sell_price, quantity,
