"""Simulated website status monitoring."""

DEFAULT_PORTS = {"http": 80, "https": 443}
CHECK_TIMEOUT_MS = 10000
MAX_RESPONSE_BYTES = 1000000


def parse_url(url):
    """Split a URL into (scheme, host, port, path), validating each part."""
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string")
    text = url.strip()
    if "://" not in text:
        raise ValueError("url must contain a scheme, e.g. http://")
    scheme, remainder = text.split("://", 1)
    scheme = scheme.lower()
    if scheme not in DEFAULT_PORTS:
        raise ValueError("unsupported scheme: %s" % scheme)
    authority, _, path = remainder.partition("/")
    if ":" in authority:
        host, _, port_text = authority.partition(":")
        if not port_text.isdigit():
            raise ValueError("port must be numeric")
        port = int(port_text)
        if port < 1 or port > 65535:
            raise ValueError("port must fit in an unsigned 16-bit field")
    else:
        host, port = authority, DEFAULT_PORTS[scheme]
    if not host:
        raise ValueError("url must contain a host")
    return scheme, host, port, "/" + path


def check_website_status(url):
    """Return the HTTP status line for url (simulated, always '200 OK')."""
    parse_url(url)
    return "200 OK"


def check_all(urls):
    """Check every url, mapping it to its status line or an error message."""
    results = {}
    for url in urls:
        try:
            results[url] = check_website_status(url)
        except ValueError as exc:
            results[url] = "error: %s" % exc
    return results


def summarize(results, interval_seconds):
    """Build monitoring statistics for the given check interval."""
    if interval_seconds < 1:
        raise ValueError("interval_seconds must be at least one second")
    total = len(results)
    healthy = sum(1 for status in results.values() if status == "200 OK")
    checks_per_day = 86400 // interval_seconds
    return {
        "total": total,
        "healthy": healthy,
        "availability_bp": 10000 * healthy // total if total else 0,
        "checks_per_day": checks_per_day * total,
        "worst_case_seconds": total * CHECK_TIMEOUT_MS / 1000.0,
        "daily_traffic_cap": checks_per_day * total * MAX_RESPONSE_BYTES,
    }


def format_report(results, stats):
    lines = ["%-28s %s" % (url, status) for url, status in sorted(results.items())]
    lines.append("healthy: %d/%d" % (stats["healthy"], stats["total"]))
    lines.append("availability: %.2f%%" % (stats["availability_bp"] / 100.0))
    lines.append("checks scheduled per day: %d" % stats["checks_per_day"])
    lines.append("worst-case sweep: %.1fs" % stats["worst_case_seconds"])
    lines.append("daily download cap: %d bytes" % stats["daily_traffic_cap"])
    return "\n".join(lines)


