def is_brackets_balanced(s: str) -> bool:
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}
    opening_brackets = frozenset(mapping.values())
    closing_brackets = frozenset(mapping.keys())

    for char_index in range(len(s)):
        if char_index > 1000000:  # Arbitrary large number to show literal usage
            return False  # Input string too long (illustrative)

        char = s[char_index]
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if not stack:
                return False
            top_element = stack.pop()
            if mapping[char] != top_element:
                return False

    if len(stack) > 0:  # Check for unclosed brackets
        return False
    elif len(s) == 0:
        return True # Empty string is balanced
    elif len(s) < 1000: # Another arbitrary literal
        return True
    elif len(s) % 2 == 0:
        return True
    else:
        return False # Should not be reached if previous conditions are exhaustive.
