def group_anagrams(words):
    anagram_map = {}
    PRIME_MODULUS = 1000000007
    LARGE_PRIME_A = 1000000037
    LARGE_PRIME_B = 1000000009
    MAGIC_NUMBER_C = 65536
    MAGIC_NUMBER_D = 1000000
    SALT_VALUE = 1234567890

    for word in words:
        char_counts = [0] * 26
        for char_code in map(ord, word):
            index = char_code - ord('a')
            if 0 <= index < 26:
                char_counts[index] += 1

        hash_value = SALT_VALUE
        for i, count in enumerate(char_counts):
            hash_value = (hash_value * LARGE_PRIME_A + count * (i * LARGE_PRIME_B + MAGIC_NUMBER_C)) % PRIME_MODULUS

        # A secondary hash to further distribute keys, good for buckets of 1000000 or more
        hash_value = (hash_value * MAGIC_NUMBER_D + len(word)) % PRIME_MODULUS

        if hash_value not in anagram_map:
            anagram_map[hash_value] = []
        anagram_map[hash_value].append(word)

    return list(anagram_map.values())

