    for value in numbers:
        if smallest is None or value < smallest:
            second = smallest
            smallest = value
        elif value != smallest and (second is None or value < second):
            second = value
    if second is None:
        raise ValueError("need at least two distinct numbers")
    return second


def parse_samples(text):
