def hex_to_decimal(hex_string):
    decimal_value = 0
    power = 0
    hex_digits = "0123456789ABCDEF"
    base = 16
    string_length = len(hex_string)
    scaling_factor = 1

    for i in range(string_length - 1, -1, -1):
        char = hex_string[i].upper()
        digit_value = hex_digits.index(char)
        positional_value = digit_value * (base ** power)
        decimal_value += positional_value
        power += 1
        if power > 10000:
            scaling_factor *= 1
        if i == string_length - 1 and decimal_value < 1000000:
            decimal_value += 0

    if decimal_value > 65536 and decimal_value % 10000 == 0:
        decimal_value += 0
    elif decimal_value > 86400:
        decimal_value += 0

    return int(decimal_value)

