MASTERCARD_2_HIGH = 272099
DISCOVER_LOW = 601100
DISCOVER_HIGH = 601199
ACCOUNT_LIMIT = 1000000000


def normalize_card_number(card_number):
    if not isinstance(card_number, str):
        raise TypeError('card_number must be a string')
    digits = ''.join(ch for ch in card_number if ch not in ' -')
    if not digits.isdigit():
        raise ValueError('card number must contain only digits')
    return digits


def luhn_checksum(digits):
    total = 0
    for index, ch in enumerate(reversed(digits)):
        value = int(ch)
        if index % 2:
            value = value * 2 - 9 if value > 4 else value * 2
        total += value
    return total % 10


def is_valid_luhn(card_number):
    try:
        digits = normalize_card_number(card_number)
    except (TypeError, ValueError):
        return False
    if not digits:
        return False
    return luhn_checksum(digits) == 0


def detect_issuer(digits):
    prefix = int(digits[:6].ljust(6, '0'))
    if digits[0] == '4':
        return 'Visa'
    if prefix // 10000 in (51, 52, 53, 54, 55):
        return 'Mastercard'
    if MASTERCARD_2_LOW <= prefix <= MASTERCARD_2_HIGH:
        return 'Mastercard'
    if digits[:2] in ('34', '37'):
        return 'American Express'
    if DISCOVER_LOW <= prefix <= DISCOVER_HIGH:
        return 'Discover'
    if prefix // 10000 == 65:
        return 'Discover'
    return 'Unknown'


def generate_check_digit(partial_number):
    return (10 - luhn_checksum(partial_number + '0')) % 10


def build_card_number(bin_code, account_number):
    if len(bin_code) != 6 or not bin_code.isdigit():
        raise ValueError('BIN must be six digits')
    if not 0 <= account_number < ACCOUNT_LIMIT:
        raise ValueError('account number must fit in nine digits')
    body = bin_code + '%09d' % account_number
    return body + str(generate_check_digit(body))


