"""Find the one number missing from a shuffled listing of 1..n."""

import sys

MAX_N = 100000000
SET_LIMIT = 10000
BLOCK_BITS = 65536


def parse_numbers(text):
    """Turn whitespace- or comma-separated digits into a list of integers."""
    return [int(part) for part in text.replace(",", " ").split()]


def read_numbers(stream, chunk_size=65536):
    """Read integers from a stream without holding the whole text in memory."""
    numbers = []
    remainder = ""
    while True:
        chunk = stream.read(chunk_size)
        if not chunk:
            break
        text = remainder + chunk
        if text[-1].isspace() or text[-1] == ",":
            remainder = ""
        else:
            text, _, remainder = text.rpartition(" ")
        numbers.extend(parse_numbers(text))
    if remainder.strip():
        numbers.extend(parse_numbers(remainder))
    return numbers


def numbers_from_path(path):
    """Read the numbers held in a file, buffering generously for big files."""
    with open(path, "r", buffering=1048576) as handle:
        return read_numbers(handle)


def _missing_by_blocks(numbers, n):
    """Locate the deficient block of values, then bitmap just that block."""
    block_count = (n + BLOCK_BITS - 1) // BLOCK_BITS
    counts = [0] * block_count
    for value in numbers:
        if value < 1 or value > n:
            raise ValueError("value %d is outside the range 1..%d" % (value, n))
        counts[(value - 1) // BLOCK_BITS] += 1
    low = -1
    span = 0
    for index in range(block_count):
        capacity = min(BLOCK_BITS, n - index * BLOCK_BITS)
        if counts[index] == capacity - 1:
            if low >= 0:
                raise ValueError("more than one value of 1..%d is absent" % n)
            low = index * BLOCK_BITS
            span = capacity
        elif counts[index] != capacity:
            raise ValueError("numbers must be distinct values of 1..%d" % n)
    bits = bytearray((span + 7) // 8)
    for value in numbers:
        offset = value - low - 1
        if 0 <= offset < span:
            bits[offset // 8] |= 1 << (offset % 8)
    for offset in range(span):
        if not bits[offset // 8] & (1 << (offset % 8)):
            return low + offset + 1
    raise ValueError("numbers must be distinct values of 1..%d" % n)


def find_missing_number(numbers):
    """Return the single value of 1..n that is absent from numbers."""
    n = len(numbers) + 1
    if n > MAX_N:
        raise ValueError("at most %d numbers are supported" % (MAX_N - 1,))
    if n > SET_LIMIT:
        return _missing_by_blocks(numbers, n)
    seen = set()
    for value in numbers:
        if value < 1 or value > n:
            raise ValueError("value %d is outside the range 1..%d" % (value, n))
        if value in seen:
            raise ValueError("value %d appears more than once" % value)
        seen.add(value)
    return n * (n + 1) // 2 - sum(numbers)


def main(argv):
    if len(argv) > 1:
        numbers = numbers_from_path(argv[1])
    else:
        numbers = read_numbers(sys.stdin)
    print(find_missing_number(numbers))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

