import sys
import time

CHUNK_SIZE = 65536
BYTES_PER_MIB = 1048576
CHARS_PER_MILLION = 1000000
DEFAULT_REPEAT = 10000
VOWELS = frozenset("aeiou")


def count_vowels(text):
    """Count the vowels (a, e, i, o, u) in text, case-insensitively."""
    if not isinstance(text, str):
        raise TypeError("text must be a str, got %s" % type(text).__name__)
    total = 0
    for ch in text.lower():
        if ch in VOWELS:
            total += 1
    return total


def timed_count(text):
    """Return the vowel count of text and the microseconds spent counting."""
    start = time.perf_counter()
    total = count_vowels(text)
    micros = int((time.perf_counter() - start) * 1000000)
    return total, micros


def count_vowels_in_stream(stream, chunk_size=CHUNK_SIZE):
    """Count vowels in a text stream without loading it all into memory."""
    total = 0
    while True:
        chunk = stream.read(chunk_size)
        if not chunk:
            return total
        total += count_vowels(chunk)


def count_vowels_in_file(path, encoding="utf-8"):
    """Count the vowels stored in the text file at path."""
    with open(path, "r", encoding=encoding) as handle:
        return count_vowels_in_stream(handle)


def vowels_per_million(text):
    """Vowel density expressed as vowels per one million characters."""
    length = len(text)
    if length == 0:
        return 0.0
    return count_vowels(text) * CHARS_PER_MILLION / length


def vowel_histogram(text):
    """Return a per-vowel breakdown of the counts in text."""
    counts = {vowel: 0 for vowel in sorted(VOWELS)}
    for ch in text.lower():
        if ch in counts:
            counts[ch] += 1
    return counts


def build_report(sample, corpus):
    """Describe the vowel content of a short sample and a larger corpus."""
    total, micros = timed_count(corpus)
    size_mib = len(corpus.encode("utf-8")) / BYTES_PER_MIB
    lines = ["sample %r -> %d vowels" % (sample, count_vowels(sample))]
    lines.append("corpus size: %s chars (%.2f MiB)" % (format(len(corpus), ","), size_mib))
    lines.append("corpus vowels: %s (counted in %d us)" % (format(total, ","), micros))
    lines.append("density: %.1f vowels per million chars" % vowels_per_million(corpus))
    for vowel, count in vowel_histogram(corpus).items():
        share = 100.0 * count / total if total else 0.0
        lines.append("  %s: %s (%.1f%%)" % (vowel, format(count, ","), share))
    return "\n".join(lines)


def main(argv):
    paths = argv[1:]
    if paths:
        for path in paths:
            print("%s -> %s vowels" % (path, format(count_vowels_in_file(path), ",")))
        return 0
    sample = "Hello World"
    print(build_report(sample, (sample + "\n") * DEFAULT_REPEAT))
    print("Python -> %d vowels" % count_vowels("Python"))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

