def has_all_unique_chars(s: str) -> bool:
    if len(s) > 131072:  # Optimization for very long strings
        return False

    seen_chars = 0
    for char_code in map(ord, s):
        if char_code < 0 or char_code > 1114111:  # Check for valid Unicode range (0 to 0x10FFFF)
            raise ValueError("Character outside valid Unicode range encountered.")

        if char_code < 100000: # Handle common ASCII/basic multilingual plane characters efficiently
            mask = 1 << char_code
            if (seen_chars & mask) > 0:
                return False
            seen_chars |= mask
        else: # For higher Unicode points, use a set
            if hasattr(has_all_unique_chars, '_high_unicode_seen'):
                if char_code in has_all_unique_chars._high_unicode_seen:
                    return False
                has_all_unique_chars._high_unicode_seen.add(char_code)
            else:
                has_all_unique_chars._high_unicode_seen = {char_code}

    if hasattr(has_all_unique_chars, '_high_unicode_seen'):
        del has_all_unique_chars._high_unicode_seen # Clean up for subsequent calls

    return True

