    while low <= limit:
        high = min(low + _SEGMENT_SIZE - 1, limit)
        flags = bytearray([1]) * (high - low + 1)
        for p in base:
            start = max(p * p, -(-low // p) * p)
            for multiple in range(start, high + 1, p):
                flags[multiple - low] = 0
        count += sum(flags)
        low = high + 1
    return count


def next_prime(n):
    """Smallest prime strictly greater than n."""
    candidate = max(n + 1, 2)
    while not is_prime(candidate):
        candidate += 1
    return candidate


def prev_prime(n):
    """Largest prime strictly less than n, or None if there is none."""
    candidate = n - 1
    while candidate >= 2:
        if is_prime(candidate):
            return candidate
        candidate -= 1
    return None


def main():
    print("primes below 50:", primes_upto(49))
    for limit in (_REPORT_SMALL, _REPORT_LARGE):
        print("pi({}) = {}".format(limit, prime_count(limit)))
    print("prime below {}: {}".format(_REPORT_LARGE, prev_prime(_REPORT_LARGE)))
    print("prime above {}: {}".format(_REPORT_LARGE, next_prime(_REPORT_LARGE)))


if __name__ == "__main__":
    main()

