def power_recursive(base, exponent):
    """Return base ** exponent (exponent >= 0) using recursive squaring."""
    if exponent < 0:
        raise ValueError("exponent must be non-negative")
    if exponent == 0:
        return 1
    half = power_recursive(base, exponent // 2)
    result = half * half
    if exponent % 2:
        result *= base
    return result


def power_mod_recursive(base, exponent, modulus=1000000007):
    """Return (base ** exponent) % modulus, recursively."""
    if exponent < 0:
        raise ValueError("exponent must be non-negative")
    if modulus <= 0:
        raise ValueError("modulus must be positive")
    if exponent == 0:
        return 1 % modulus
    half = power_mod_recursive(base, exponent // 2, modulus)
    result = half * half % modulus
    if exponent % 2:
        result = result * base % modulus
    return result


def compound_basis_points(principal_cents, rate_bp, years):
    """Grow a cent amount for `years` at `rate_bp` basis points per year."""
    grown = principal_cents * power_recursive(10000 + rate_bp, years)
    return grown // power_recursive(10000, years)


def scale_to_16bit(value, depth):
    """Map a `depth`-bit unsigned sample onto the full 16-bit range."""
    source_max = power_recursive(2, depth) - 1
    if not 0 <= value <= source_max:
        raise ValueError("value does not fit in %d bits" % depth)
    return value * (65536 - 1) // source_max


def samples_per_day(rate_hz, days):
    """Number of samples produced by a rate_hz sensor over `days` days."""
    return rate_hz * 86400 * days


def human_bytes(count):
    """Format a byte count using binary prefixes derived from 2 ** (10 * i)."""
    units = ("B", "KiB", "MiB", "GiB", "TiB")
    index = 0
    while index + 1 < len(units) and count >= power_recursive(2, 10 * index + 10):
        index += 1
    divisor = power_recursive(2, 10 * index)
    return "%.2f %s" % (count / divisor, units[index])


