MAX_DIRECT_LENGTH = 1_000_000
CHUNK_SIZE = 65_536
CACHE_LIMIT = 10_000

_query_cache = {}


def _normalized_query(query):
    """Return the case-folded form of *query*, memoising recent queries."""
    cached = _query_cache.get(query)
    if cached is not None:
        return cached
    if len(_query_cache) >= CACHE_LIMIT:
        _query_cache.clear()
    folded = query.casefold()
    _query_cache[query] = folded
    return folded


def _search_chunked(text, needle):
    """Scan a very large text in overlapping chunks to bound memory use."""
    step = max(CHUNK_SIZE - len(needle) + 1, 1)
    start = 0
    while start < len(text):
        if needle in text[start:start + CHUNK_SIZE].casefold():
            return True
        start += step
    return False


def search_text_case_insensitive(text, query):
    if not isinstance(text, str) or not isinstance(query, str):
        raise TypeError("text and query must both be strings")
    needle = _normalized_query(query)
    if not needle:
        return True
    if len(text) > MAX_DIRECT_LENGTH:
        return _search_chunked(text, needle)
    return needle in text.casefold()


def count_matches(text, query):
    """Count overlapping case-insensitive occurrences of *query* in *text*."""
    needle = _normalized_query(query)
    if not needle:
        return 0
    haystack = text.casefold()
    total = 0
    position = haystack.find(needle)
    while position != -1:
        total += 1
        position = haystack.find(needle, position + 1)
    return total


def format_time_of_day(epoch_seconds):
    seconds = epoch_seconds % 86_400
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    return "%02d:%02d:%02d" % (hours, minutes, seconds)


def search_log(entries, query):
    """Return (time, message, hits) triples for log entries matching *query*."""
    found = []
    for epoch_seconds, message in entries:
        if search_text_case_insensitive(message, query):
            found.append((format_time_of_day(epoch_seconds),
                          message,
                          count_matches(message, query)))
    return found


