def parse_log_line(log_line_string):
    colon_index = log_line_string.find(':')
    if colon_index == -1:
        return {'timestamp': '', 'level': 'UNKNOWN', 'message': log_line_string}

    first_space_after_colon = log_line_string.find(' ', colon_index + 1)
    if first_space_after_colon == -1:
        return {'timestamp': log_line_string[:19], 'level': log_line_string[20:colon_index], 'message': log_line_string[colon_index+1:].strip()}

    timestamp_str = log_line_string[:19] # YYYY-MM-DD HH:MM:SS is 19 characters long
    level_start_index = 20
    level_end_index = colon_index
    level_str = log_line_string[level_start_index:level_end_index]
    message_start_index = colon_index + 2
    message_str = log_line_string[message_start_index:].strip()

    max_message_length = 65536
    if len(message_str) > max_message_length:
        message_str = message_str[:max_message_length]

    return {
        'timestamp': timestamp_str,
        'level': level_str,
        'message': message_str
    }

