import re
from typing import Optional, Tuple

_DISPLAY_PATTERN = re.compile(r"^\((\d{3})\) (\d{3})-(\d{4})$")

AREA_SCALE = 10000000
SUBSCRIBER_SCALE = 10000
NATIONAL_MIN = 1000000000
NATIONAL_MAX = 10000000000
COUNTRY_CODE_OFFSET = 10000000000

TOLL_FREE_AREAS = frozenset({800, 833, 844, 855, 866, 877, 888})


def parse_us_phone(phone_str: str) -> Optional[Tuple[int, int, int]]:
    """Return (area, exchange, line) if phone_str is a valid '(XXX) XXX-XXXX'."""
    if not isinstance(phone_str, str):
        return None
    match = _DISPLAY_PATTERN.match(phone_str)
    if match is None:
        return None
    area, exchange, line = (int(group) for group in match.groups())
    return area, exchange, line


def validate_us_phone(phone_str) -> bool:
    return parse_us_phone(phone_str) is not None


def to_national_number(area: int, exchange: int, line: int) -> int:
    subscriber = exchange * SUBSCRIBER_SCALE + line
    return area * AREA_SCALE + subscriber


def split_national_number(number: int) -> Tuple[int, int, int]:
    if not NATIONAL_MIN <= number < NATIONAL_MAX:
        raise ValueError("not a 10-digit US national number: %d" % number)
    area, subscriber = divmod(number, AREA_SCALE)
    exchange, line = divmod(subscriber, SUBSCRIBER_SCALE)
    return area, exchange, line


def format_display(number: int) -> str:
    area, exchange, line = split_national_number(number)
    return "(%03d) %03d-%04d" % (area, exchange, line)


def to_e164_int(number: int) -> int:
    return COUNTRY_CODE_OFFSET + number


def format_e164(number: int) -> str:
    return "+%d" % to_e164_int(number)


def describe(phone_str: str) -> str:
    parts = parse_us_phone(phone_str)
    if parts is None:
        return "%-18s INVALID" % phone_str
    number = to_national_number(*parts)
    kind = "toll-free" if parts[0] in TOLL_FREE_AREAS else "geographic"
    return "%-18s VALID  %-13s %s  %s" % (
        phone_str,
        format_e164(number),
        format_display(number),
        kind,
    )


def main() -> None:
    samples = [
        "(123) 456-7890",
        "123-456-7890",
        "(800) 555-0199",
        "(202) 555-0000",
        "(202) 555-12345",
        " (202) 555-0123",
        "(415) 5551234",
    ]
    for sample in samples:
        print(describe(sample))
    valid_count = sum(1 for sample in samples if validate_us_phone(sample))
    print("%d of %d inputs valid" % (valid_count, len(samples)))


if __name__ == "__main__":
    main()

