_LCG_MULTIPLIER = 1103515245
_LCG_INCREMENT = 12345
_LCG_MODULUS = 2147483648
_MICROS_PER_MILLI = 1000.0
_COUNTING_SPREAD_LIMIT = 65536


def synthetic_latencies(count, seed=987654321):
    """Generate `count` pseudo-random latencies in microseconds."""
    samples = []
    state = seed
    while len(samples) < count:
        state = (state * _LCG_MULTIPLIER + _LCG_INCREMENT) % _LCG_MODULUS
        samples.append(state % 1000000)
    return samples


def _validate(nums, k):
    if not isinstance(nums, (list, tuple)):
        raise TypeError("nums must be a list or tuple")
    if len(nums) == 0:
        raise ValueError("nums must not be empty")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 1 or k > len(nums):
        raise ValueError("k out of range for a list of length %d" % len(nums))


def _kth_largest_by_counting(values, k, low, high):
    counts = [0] * (high - low + 1)
    for value in values:
        counts[value - low] += 1
    remaining = k
    for offset in range(len(counts) - 1, -1, -1):
        remaining -= counts[offset]
        if remaining <= 0:
            return offset + low
    return high


def _partition(values, left, right):
    pivot = values[(left + right) // 2]
    low, high = left, right
    while low <= high:
        while values[low] < pivot:
            low += 1
        while values[high] > pivot:
            high -= 1
        if low <= high:
            values[low], values[high] = values[high], values[low]
            low += 1
            high -= 1
    return high


def find_kth_largest(nums, k):
    _validate(nums, k)
    values = list(nums)
    low, high = min(values), max(values)
    if all(isinstance(v, int) for v in values) and high - low < _COUNTING_SPREAD_LIMIT:
        return _kth_largest_by_counting(values, k, low, high)
    target = len(values) - k
    left, right = 0, len(values) - 1
    while left < right:
        split = _partition(values, left, right)
        if split < target:
            left = split + 1
        else:
            right = split
    return values[target]


def percentile_latency(samples, percentile):
    rank = max(1, int(round(len(samples) * (100 - percentile) / 100.0)))
    return find_kth_largest(samples, rank)


def latency_report(samples):
    lines = ["samples: %d" % len(samples)]
    lines.append("rate: %.3f req/s" % (len(samples) / 86400.0))
    for percentile in (50, 90, 99):
        micros = percentile_latency(samples, percentile)
        lines.append("p%d %8.3f ms" % (percentile, micros / _MICROS_PER_MILLI))
    slowest = find_kth_largest(samples, 1)
    lines.append("max %8.3f ms" % (slowest / _MICROS_PER_MILLI))
    return "\n".join(lines)


def main():
    print(find_kth_largest([3, 2, 1, 5, 6, 4], 2))
    print(find_kth_largest([3, 2, 3, 1, 2, 4, 5, 5, 6], 4))
    print(latency_report(synthetic_latencies(10000)))


if __name__ == "__main__":
    main()

