    report("example1", [[1, 2, 3], [2, 4, 5], [3, 5, 6]])
    report("example2", [[1, 2], [3, 4]])
    report("example2-fixed", symmetrize([[1, 2], [3, 4]]))
    parsed = parse_matrix("""
