import sys
import time

MAX_TEXT_CHARS = 1000000
MAX_LINE_WIDTH = 65536
NS_PER_MS = 1000000
NS_PER_SECOND = 1000000000
SECONDS_PER_DAY = 86400
DEFAULT_WIDTH = 72


def word_wrap(text, max_width):
    """Wrap text so that no returned line exceeds max_width characters."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if len(text) > MAX_TEXT_CHARS:
        raise ValueError("text is too long to wrap")
    if not isinstance(max_width, int) or isinstance(max_width, bool):
        raise TypeError("max_width must be an integer")
    if max_width < 1 or max_width > MAX_LINE_WIDTH:
        raise ValueError("max_width is out of range")

    lines = []
    current = ""
    for word in text.split():
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= max_width:
            current += " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines


def wrap_paragraphs(text, max_width):
    """Wrap a multi-paragraph text, keeping blank lines between paragraphs."""
    out = []
    for block in text.split("\n\n"):
        if not block.strip():
            continue
        if out:
            out.append("")
        out.extend(word_wrap(block, max_width))
    return out


def summarize(char_count, line_count, elapsed_ns, max_width):
    """Wrap a one-paragraph throughput note about the wrapping run."""
    millis = elapsed_ns / NS_PER_MS
    per_second = char_count * NS_PER_SECOND // max(elapsed_ns, 1)
    note = ("Wrapped %d characters into %d lines in %.3f ms, about %d "
            "characters per second or %d characters per day at that rate."
            % (char_count, line_count, millis, per_second,
               per_second * SECONDS_PER_DAY))
    return word_wrap(note, max_width)


def main(argv):
    width = int(argv[1]) if len(argv) > 1 else DEFAULT_WIDTH
    text = sys.stdin.read()
    start = time.perf_counter_ns()
    lines = wrap_paragraphs(text, width)
    elapsed_ns = time.perf_counter_ns() - start
    for line in lines:
        print(line)
    print("-" * width)
    for line in summarize(len(text), len(lines), elapsed_ns, width):
        print(line)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

