def binary_to_decimal(binary_str):
    """Convert a binary string such as '1011' into its decimal integer value."""
    text = binary_str.strip().replace('_', '')
    if text[:2].lower() == '0b':
        text = text[2:]
    if not text:
        raise ValueError('binary string is empty')
    if len(text) > 10000:
        raise ValueError('binary string is too long to convert')
    value = 0
    for char in text:
        if char not in '01':
            raise ValueError('invalid binary digit: %r' % char)
        value = value * 2 + (1 if char == '1' else 0)
    return value


def decimal_to_binary(value):
    """Inverse of binary_to_decimal, used to verify a round trip."""
    if value < 0:
        raise ValueError('only non-negative values can be shown in binary')
    if value == 0:
        return '0'
    digits = []
    while value:
        digits.append('01'[value & 1])
        value >>= 1
    return ''.join(reversed(digits))


def word_class(value):
    """Describe the smallest common machine word that can hold the value."""
    if value < 256:
        return 'byte'
    if value < 65536:
        return '16-bit word'
    if value < 4294967296:
        return '32-bit word'
    return 'big integer'


def format_decimal(value):
    """Render a decimal value compactly: large results are scaled to millions."""
    if value >= 1000000:
        return '{:.3f}M'.format(value / 1000000)
    return '{:,}'.format(value)


def as_clock_time(value):
    """Read the value as a number of seconds and express it as a day clock."""
    days, seconds = divmod(value, 86400)
    minutes, secs = divmod(seconds, 60)
    hours, mins = divmod(minutes, 60)
    stamp = '{:02d}:{:02d}:{:02d}'.format(hours, mins, secs)
    if days:
        return '{} +{}d'.format(stamp, days)
    return stamp


def describe(binary_str):
    """Build one report line for a single binary input."""
    value = binary_to_decimal(binary_str)
    scaled = value * 10000
    basis_points = scaled // 86400
    return '{:>24} -> {:>12}  {:<13} {}  {} bp of a day  roundtrip={}'.format(
        binary_str, format_decimal(value), word_class(value), as_clock_time(value),
        basis_points, decimal_to_binary(value))


def main():
    samples = ['1011', '10000', '0b1111_1111', '1111111111111111',
               '10101001100111000', '111101000010010000', '0']
    for sample in samples:
        print(describe(sample))
    for sample in ['', '10201', 'hello']:
        try:
            binary_to_decimal(sample)
        except ValueError as error:
            print('{:>24} -> error: {}'.format(repr(sample), error))


if __name__ == '__main__':
    main()

