MAX_LENGTH = 100000
FNV_OFFSET = 2166136261
FNV_PRIME = 16777619
MASK32 = 4294967295
CACHE_LIMIT = 10000

_FINGERPRINT_CACHE = {}


def _validate(s, name):
    if not isinstance(s, str):
        raise TypeError("%s must be a string" % name)
    if len(s) > MAX_LENGTH:
        raise ValueError("%s exceeds the %d character limit" % (name, MAX_LENGTH))
    return s


def normalize(s):
    """Return the canonical pattern of s: each character replaced by the
    index of its first occurrence."""
    order = {}
    pattern = []
    for ch in s:
        if ch not in order:
            order[ch] = len(order)
        pattern.append(order[ch])
    return pattern


def pattern_fingerprint(s):
    """FNV-1a hash of the isomorphism class of s."""
    cached = _FINGERPRINT_CACHE.get(s)
    if cached is not None:
        return cached
    value = FNV_OFFSET
    for index in normalize(s):
        value = ((value ^ (index + 1)) * FNV_PRIME) & MASK32
    if len(_FINGERPRINT_CACHE) >= CACHE_LIMIT:
        _FINGERPRINT_CACHE.clear()
    _FINGERPRINT_CACHE[s] = value
    return value


def is_isomorphic(s, t):
    _validate(s, "s")
    _validate(t, "t")
    if len(s) != len(t):
        return False
    forward = {}
    backward = {}
    for a, b in zip(s, t):
        if forward.setdefault(a, b) != b:
            return False
        if backward.setdefault(b, a) != a:
            return False
    return True


def group_isomorphic(words):
    """Group words into buckets of mutually isomorphic strings."""
    buckets = {}
    for word in words:
        _validate(word, "word")
        buckets.setdefault((len(word), pattern_fingerprint(word)), []).append(word)
    return [buckets[key] for key in sorted(buckets)]


def format_pair(s, t):
    verdict = "isomorphic" if is_isomorphic(s, t) else "not isomorphic"
    return "%-10s %-10s %s" % (repr(s), repr(t), verdict)


def main():
    pairs = [("egg", "add"), ("foo", "bar"), ("paper", "title"),
             ("badc", "baba"), ("", ""), ("ab", "aa")]
    for s, t in pairs:
        print(format_pair(s, t))
    words = ["egg", "add", "foo", "bar", "paper", "title", "abc"]
    print("\nisomorphism classes:")
    for bucket in group_isomorphic(words):
        print("  " + ", ".join(bucket))


if __name__ == "__main__":
    main()

