import math

M2_PER_HECTARE = 10000
MM2_PER_M2 = 1000000
SECONDS_PER_DAY = 86400
SECONDS_PER_YEAR = 31557600
FIXED_POINT_SCALE = 65536
FIXED_POINT_MAX = 2147483647


def circle_area(radius: float) -> float:
    """Area of a circle of the given radius, in squared input units."""
    if radius < 0:
        raise ValueError("radius must be non-negative")
    return math.pi * radius * radius


def area_in_hectares(radius_m: float) -> float:
    """Area of a circular plot of radius_m metres, expressed in hectares."""
    return circle_area(radius_m) / M2_PER_HECTARE


def area_in_mm2(radius_m: float) -> float:
    """Area of a circle of radius_m metres, expressed in square millimetres."""
    return circle_area(radius_m) * MM2_PER_M2


def daily_volume(radius_m: float, speed_mps: float) -> float:
    """Cubic metres passing through a circular pipe in one full day."""
    if speed_mps < 0:
        raise ValueError("speed must be non-negative")
    return circle_area(radius_m) * speed_mps * SECONDS_PER_DAY


def yearly_volume(radius_m: float, speed_mps: float) -> float:
    """Cubic metres passing through a circular pipe in one Julian year."""
    if speed_mps < 0:
        raise ValueError("speed must be non-negative")
    return circle_area(radius_m) * speed_mps * SECONDS_PER_YEAR


def to_fixed_point(value: float) -> int:
    """Encode a value as a 16.16 fixed-point integer."""
    raw = int(round(value * FIXED_POINT_SCALE))
    if raw > FIXED_POINT_MAX:
        raise OverflowError("value too large for 16.16 fixed point")
    return raw


def from_fixed_point(raw: int) -> float:
    """Decode a 16.16 fixed-point integer back to a float."""
    return raw / FIXED_POINT_SCALE


def format_row(radius_m: float, speed_mps: float) -> str:
    area = circle_area(radius_m)
    raw = to_fixed_point(area)
    return (
        f"r={radius_m:7.3f} m | area={area:12.4f} m^2 | "
        f"{area_in_hectares(radius_m):9.6f} ha | "
        f"{area_in_mm2(radius_m):16.1f} mm^2 | "
        f"day={daily_volume(radius_m, speed_mps):12.2f} m^3 | "
        f"year={yearly_volume(radius_m, speed_mps):14.1f} m^3 | "
        f"fx={raw:d} ({from_fixed_point(raw):.4f})"
    )


def report(radii, speed_mps=1.5):
    lines = [format_row(r, speed_mps) for r in radii]
    total = sum(circle_area(r) for r in radii)
    lines.append(f"total area = {total:.4f} m^2 = {total / M2_PER_HECTARE:.6f} ha")
    return "\n".join(lines)


def main():
    print(f"circle_area(1) = {circle_area(1):.5f}")
    print(f"circle_area(0) = {circle_area(0):.1f}")
    print(report([0, 0.25, 1, 2.5, 56.4189, 100]))


if __name__ == "__main__":
    main()

