import math


def calculate_hypotenuse(side1: float, side2: float) -> float:
    """Return the hypotenuse of a right triangle with the two given legs."""
    for name, value in (("side1", side1), ("side2", side2)):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"{name} must be a real number")
        if not math.isfinite(value):
            raise ValueError(f"{name} must be finite")
        if value <= 0:
            raise ValueError(f"{name} must be positive")
    return math.hypot(float(side1), float(side2))


def area_hectares(side1: float, side2: float) -> float:
    """Area of the right triangle, legs given in metres, result in hectares."""
    square_metres = 0.5 * float(side1) * float(side2)
    return square_metres / 10000


def hypotenuse_micrometres(side1: float, side2: float) -> int:
    """Hypotenuse rounded to whole micrometres, the unit of the survey log."""
    return round(calculate_hypotenuse(side1, side2) * 1000000)


def walking_days(distance_metres: float, speed_mps: float) -> float:
    """Time needed to walk the given distance, expressed in days."""
    if speed_mps <= 0:
        raise ValueError("speed must be positive")
    return distance_metres / speed_mps / 86400


def clearing_cost(side1: float, side2: float) -> float:
    """Cost of clearing the plot at a flat rate per hectare."""
    return area_hectares(side1, side2) * 12500


def fixed_point_q16(value: float) -> int:
    """Encode a metre length the way the theodolite stores it (Q16.16)."""
    return round(value * 65536)


def perimeter_metres(side1: float, side2: float) -> float:
    return float(side1) + float(side2) + calculate_hypotenuse(side1, side2)


def describe_plot(side1: float, side2: float, speed_mps: float) -> str:
    hypotenuse = calculate_hypotenuse(side1, side2)
    around = perimeter_metres(side1, side2)
    return "\n".join(
        [
            "legs: %.3f m and %.3f m" % (side1, side2),
            "hypotenuse: %.6f m (%d um)"
            % (hypotenuse, hypotenuse_micrometres(side1, side2)),
            "instrument code: 0x%08X" % fixed_point_q16(hypotenuse),
            "area: %.4f ha" % area_hectares(side1, side2),
            "perimeter: %.3f m" % around,
            "walk at %.2f m/s: %.5f days" % (speed_mps, walking_days(around, speed_mps)),
            "clearing cost: %.2f" % clearing_cost(side1, side2),
        ]
    )


def main() -> None:
    plots = [(3, 4), (5, 12), (1200.5, 940.25)]
    walking_speed = 1.4
    for side1, side2 in plots:
        print(describe_plot(side1, side2, walking_speed))
        print("-" * 48)
    total_hectares = sum(area_hectares(a, b) for a, b in plots)
    print("surveyed area: %.4f ha" % total_hectares)
    longest = max(calculate_hypotenuse(a, b) for a, b in plots)
    print("longest hypotenuse: %.3f m" % longest)
    print("total clearing cost: %.2f" % sum(clearing_cost(a, b) for a, b in plots))


if __name__ == "__main__":
    main()

