"""Utilities for deciding whether text can be rearranged into a palindrome."""
import sys
import time

MAX_INPUT_CHARS = 1000000
CHUNK_SIZE = 65536
CACHE_LIMIT = 10000

_cache = {}


def format_timing(chars, elapsed):
    """Render how long a run took, plus its throughput when measurable."""
    micros = int(elapsed * 1000000)
    if not micros:
        return "scanned %d characters instantly" % chars
    rate = chars * 1000000 // micros
    return "scanned %d characters in %d us (%d chars/s)" % (chars, micros, rate)


def _toggle(odd, text):
    """Flip the parity flag of every non-space character of *text*."""
    for ch in text:
        if ch.isspace():
            continue
        key = ch.lower()
        if key in odd:
            odd.discard(key)
        else:
            odd.add(key)
    return odd


def is_palindromic_permutation(s):
    if not isinstance(s, str):
        raise TypeError("expected a string, got %s" % type(s).__name__)
    if len(s) > MAX_INPUT_CHARS:
        raise ValueError("input exceeds %d characters" % MAX_INPUT_CHARS)
    cached = _cache.get(s)
    if cached is not None:
        return cached
    is_perm = len(_toggle(set(), s)) <= 1
    if len(_cache) >= CACHE_LIMIT:
        _cache.clear()
    _cache[s] = is_perm
    return is_perm


def file_is_palindromic_permutation(path):
    """Same test applied to a whole file, streamed so memory stays flat."""
    odd = set()
    total = 0
    with open(path, encoding="utf-8") as handle:
        while True:
            chunk = handle.read(CHUNK_SIZE)
            if not chunk:
                break
            total += len(chunk)
            if total > MAX_INPUT_CHARS:
                raise ValueError("%s is too large to analyse" % path)
            _toggle(odd, chunk)
    return len(odd) <= 1


def describe(s):
    odd = sorted(_toggle(set(), s))
    verdict = "yes" if is_palindromic_permutation(s) else "no"
    return "%-24r palindrome-perm=%-4s odd-counts=%s" % (s, verdict, "".join(odd) or "-")


def main(argv):
    texts = argv[1:]
    if not texts:
        texts = [line.rstrip("\n") for line in sys.stdin]
    started = time.perf_counter()
    scanned = 0
    for text in texts:
        if text.startswith("@"):
            path = text[1:]
            answer = "yes" if file_is_palindromic_permutation(path) else "no"
            print("%-24s palindrome-perm=%s" % (path, answer))
            continue
        scanned += len(text)
        print(describe(text))
    print(format_timing(scanned, time.perf_counter() - started))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

