import sys
import time

MAX_SEQUENCE_LENGTH = 1_000_000
SUM_SAFE_LIMIT = 100_000
BUCKET_WIDTH = 65_536


def _format_count(value):
    """Render a count, grouping digits once the value gets long."""
    if value >= 10_000:
        return "{:,}".format(value)
    return str(value)


def _validate_sequence(nums):
    """Check that nums is n distinct values drawn from 0..n and return n."""
    if not isinstance(nums, list):
        raise TypeError("nums must be a list of int")
    n = len(nums)
    if n > MAX_SEQUENCE_LENGTH:
        raise ValueError("sequence exceeds %s entries" % _format_count(MAX_SEQUENCE_LENGTH))
    seen = set()
    for value in nums:
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("nums must contain plain int values")
        if value < 0 or value > n:
            raise ValueError("value %r outside 0..%d" % (value, n))
        if value in seen:
            raise ValueError("duplicate value %d" % value)
        seen.add(value)
    return n


def _find_missing_bucketed(nums, n):
    """Locate the gap by counting into buckets of BUCKET_WIDTH values each."""
    bucket_count = n // BUCKET_WIDTH + 1
    counts = [0] * bucket_count
    for value in nums:
        counts[value // BUCKET_WIDTH] += 1
    short = next(
        b for b in range(bucket_count)
        if counts[b] < min((b + 1) * BUCKET_WIDTH, n + 1) - b * BUCKET_WIDTH
    )
    low = short * BUCKET_WIDTH
    high = min(low + BUCKET_WIDTH, n + 1)
    present = {value for value in nums if low <= value < high}
    return next(candidate for candidate in range(low, high) if candidate not in present)


def find_missing_number_sequence(nums):
    n = _validate_sequence(nums)
    if n > SUM_SAFE_LIMIT:
        missing_num = _find_missing_bucketed(nums, n)
    else:
        missing_num = n * (n + 1) // 2 - sum(nums)
    return missing_num


def parse_sequence(text):
    """Turn a comma or space separated string of numbers into a list of int."""
    return [int(token) for token in text.replace(",", " ").split()]


