    missing_num = find_missing_number_sequence(nums)
    elapsed_us = int((time.perf_counter() - start) * 1_000_000)
    return "count=%s range=0..%s missing=%d time=%dus" % (
        _format_count(len(nums)), _format_count(len(nums)), missing_num, elapsed_us)


