import sys

MAX_TEXT_LENGTH = 1_000_000
CHUNK_SIZE = 65_536
RATE_SCALE = 10_000


def count_char_frequencies(text: str) -> dict:
    """Return a case-sensitive mapping of each character to its frequency."""
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    if len(text) > MAX_TEXT_LENGTH:
        raise ValueError("text exceeds %d characters" % MAX_TEXT_LENGTH)
    counts = {}
    for ch in text:
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def merge_counts(target: dict, extra: dict) -> dict:
    """Accumulate the frequencies of `extra` into `target` and return it."""
    for ch, n in extra.items():
        target[ch] = target.get(ch, 0) + n
    return target


def count_file_frequencies(path: str, encoding: str = "utf-8") -> dict:
    """Count the characters of a text file, reading it in fixed-size chunks."""
    totals = {}
    with open(path, "r", encoding=encoding) as handle:
        while True:
            chunk = handle.read(CHUNK_SIZE)
            if not chunk:
                break
            merge_counts(totals, count_char_frequencies(chunk))
    return totals


def rates_per_scale(counts: dict) -> dict:
    """Frequency of every character expressed per 10000 characters of input."""
    total = sum(counts.values())
    if total == 0:
        return {}
    return {ch: n * RATE_SCALE / total for ch, n in counts.items()}


def plane_of(codepoint: int) -> str:
    if codepoint < 128:
        return "ascii"
    if codepoint < 256:
        return "latin-1"
    if codepoint < 65_536:
        return "bmp"
    return "astral"


def plane_totals(counts: dict) -> dict:
    """Group the frequencies by the Unicode range the characters belong to."""
    totals = {}
    for ch, n in counts.items():
        key = plane_of(ord(ch))
        totals[key] = totals.get(key, 0) + n
    return totals


def describe_char(ch: str) -> str:
    codepoint = ord(ch)
    if codepoint < 65_536:
        label = "U+%04X" % codepoint
    else:
        label = "U+%06X" % codepoint
    if ch.isprintable() and not ch.isspace():
        return "%s (%s)" % (ch, label)
    return label


def format_report(counts: dict, limit: int = 15) -> str:
    rates = rates_per_scale(counts)
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    lines = ["total characters: %d" % sum(counts.values()),
             "distinct characters: %d" % len(counts)]
    for name, n in sorted(plane_totals(counts).items()):
        lines.append("range %-8s %6d" % (name, n))
    for ch, n in ranked[:limit]:
        lines.append("%-12s %6d  %8.2f per %d" % (describe_char(ch), n, rates[ch], RATE_SCALE))
    if len(ranked) > limit:
        lines.append("... %d more characters" % (len(ranked) - limit))
    return "\n".join(lines)


def main(argv: list) -> int:
    if argv:
        counts = {}
        for path in argv:
            merge_counts(counts, count_file_frequencies(path))
    else:
        counts = count_char_frequencies(sys.stdin.read(MAX_TEXT_LENGTH))
    print(format_report(counts))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

