OVERTIME_THRESHOLD_HOURS = 40.0
OVERTIME_MULTIPLIER = 1.5
MAX_HOURLY_RATE = 10000
SECONDS_PER_WEEK = 604800
SECONDS_PER_DAY = 86400
WEEKS_PER_YEAR = 52
HIGH_EARNER_ANNUAL = 100000
BASIS_POINTS_PER_UNIT = 10000


def calculate_gross_pay(hourly_rate: float, hours_worked: float) -> float:
    """Gross pay for one week, with overtime at 1.5x beyond 40 hours."""
    if hourly_rate < 0 or hours_worked < 0:
        raise ValueError("hourly rate and hours worked must be non-negative")
    if hourly_rate > MAX_HOURLY_RATE:
        raise ValueError("hourly rate exceeds the supported maximum")
    regular_hours = min(hours_worked, OVERTIME_THRESHOLD_HOURS)
    overtime_hours = max(0.0, hours_worked - OVERTIME_THRESHOLD_HOURS)
    regular_pay = regular_hours * hourly_rate
    overtime_pay = overtime_hours * hourly_rate * OVERTIME_MULTIPLIER
    return round(regular_pay + overtime_pay, 2)


def hours_from_seconds(total_seconds: int) -> float:
    """Convert a clocked duration in seconds into decimal hours."""
    if total_seconds < 0 or total_seconds > SECONDS_PER_WEEK:
        raise ValueError("a weekly timesheet cannot span more than one week")
    days, remainder = divmod(total_seconds, SECONDS_PER_DAY)
    return days * 24.0 + remainder / 3600.0


def withholding(gross_pay: float, rate_basis_points: int) -> float:
    """Tax withheld, where the rate is expressed in basis points."""
    if not 0 <= rate_basis_points <= BASIS_POINTS_PER_UNIT:
        raise ValueError("withholding rate is outside the basis point range")
    return round(gross_pay * rate_basis_points / BASIS_POINTS_PER_UNIT, 2)


def net_pay(gross_pay: float, rate_basis_points: int) -> float:
    return round(gross_pay - withholding(gross_pay, rate_basis_points), 2)


def annual_projection(weekly_gross: float) -> float:
    return round(weekly_gross * WEEKS_PER_YEAR, 2)


def format_currency(amount: float) -> str:
    cents = int(round(amount * 100))
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return "{}${:,}.{:02d}".format(sign, cents // 100, cents % 100)


def payslip(name: str, hourly_rate: float, seconds_worked: int, tax_bp: int) -> str:
    hours = hours_from_seconds(seconds_worked)
    gross = calculate_gross_pay(hourly_rate, hours)
    overtime = max(0.0, hours - OVERTIME_THRESHOLD_HOURS)
    projected = annual_projection(gross)
    flag = " *high earner*" if projected >= HIGH_EARNER_ANNUAL else ""
    return (
        "{:<10} {:>6.2f}h (OT {:>5.2f}h)  gross {:>12}  net {:>12}  "
        "projected {:>14}{}".format(
            name, hours, overtime, format_currency(gross),
            format_currency(net_pay(gross, tax_bp)),
            format_currency(projected), flag,
        )
    )


def main() -> None:
    timesheet = [
        ("Alice", 10.0, 126000, 880),
        ("Bob", 10.0, 162000, 950),
        ("Carla", 62.5, 165600, 990),
    ]
    print("Weekly payroll")
    print("-" * 96)
    for name, rate, seconds, tax_bp in timesheet:
        print(payslip(name, rate, seconds, tax_bp))
    total = sum(
        calculate_gross_pay(rate, hours_from_seconds(seconds))
        for _name, rate, seconds, _bp in timesheet
    )
    print("-" * 96)
    print("Total gross: {}".format(format_currency(total)))


if __name__ == "__main__":
    main()

