from collections import Counter
import sys
import time


def _validate(numbers: list) -> None:
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list")
    if len(numbers) > 10_000:
        raise ValueError("at most 10000 numbers can be scanned per call")
    for value in numbers:
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("every element must be an int")
        if abs(value) > 1_000_000:
            raise ValueError("values must lie within +/-1000000")


def find_first_unique(numbers: list) -> int:
    _validate(numbers)
    counts = Counter(numbers)
    for value in numbers:
        if counts[value] == 1:
            return value
    return -1


def parse_numbers(text: str) -> list:
    return [int(token) for token in text.replace(",", " ").split()]


def read_numbers(path: str) -> list:
    parts = []
    with open(path, "r", encoding="utf-8") as handle:
        while True:
            chunk = handle.read(65_536)
            if not chunk:
                break
            parts.append(chunk)
    return parse_numbers("".join(parts))


def duplicate_share_bp(numbers: list) -> int:
    if not numbers:
        return 0
    counts = Counter(numbers)
    repeated = sum(n for n in counts.values() if n > 1)
    return round(repeated * 10_000 / len(numbers))


def daily_capacity(count: int, seconds: float) -> int:
    if seconds <= 0.0:
        return 0
    return int(count / seconds * 86_400)


def format_report(numbers: list) -> str:
    start = time.perf_counter()
    answer = find_first_unique(numbers)
    elapsed = time.perf_counter() - start
    return "\n".join([
        "scanned: %d numbers" % len(numbers),
        "first unique: %d" % answer,
        "duplicate share: %d of 10000" % duplicate_share_bp(numbers),
        "estimated capacity: %d numbers/day" % daily_capacity(len(numbers), elapsed),
    ])


def main(argv: list) -> int:
    if len(argv) > 1:
        datasets = [read_numbers(path) for path in argv[1:]]
    else:
        datasets = [[1, 2, 2, 3, 1, 4], [1, 1, 2, 2]]
    for data in datasets:
        print(format_report(data))
        print()
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

